template <typename T> void forward_to(T&& arg) { std::forward<T>(arg); }

// Example showing perfect forwarding to a function expecting a const T&:
template<typename T> void myFunc(const T& val) { /* ... */ }

template<typename T> void perfectForwardingExample(T&& val) {
  myFunc(std::forward<T>(val)); // Forwards val without unnecessary copy
}

// Example illustrating the use of std::forward to prevent unnecessary copies
template <typename T> void log_value(T&& value) {
  // Avoids copying if possible.
  std::cout << value << std::endl; 
}

int main() {
  int x = 10;
  log_value(x);             // T is int&, no copy
  log_value(std::move(x)); // T is int&&, move semantic applied (if applicable)
  log_value(10);          // T is int&&, copy elision possible
}
